import { createGetterSetter } from '../../opensearch_dashboards_utils/public';
export const [getData, setData] = createGetterSetter('Data');
export const [getDataSourceEnabled, setDataSourceEnabled] = createGetterSetter('DataSource');
export const [getSavedObjectsClient, setSavedObjectsClient] = createGetterSetter('SavedObjects');
export const [getNotifications, setNotifications] = createGetterSetter('Notifications');
export const [getUiActions, setUiActions] = createGetterSetter('UIActions');
export const [getUISettings, setUISettings] = createGetterSetter('UISettings');
export const [getInjectedMetadata, setInjectedMetadata] = createGetterSetter('InjectedMetadata');
export const [getInjectedVars, setInjectedVars] = createGetterSetter('InjectedVars');
export const [getMapsLegacyConfig, setMapsLegacyConfig] = createGetterSetter('MapsLegacyConfig');
export const getEnableExternalUrls = () => getInjectedVars().enableExternalUrls;
export const getExposeDebugObjectToWindow = () => getInjectedVars().exposeDebugObjectToWindow;
export const getEmsTileLayerId = () => getMapsLegacyConfig().emsTileLayerId;
export const getShowRegionDeniedWarning = () => getMapsLegacyConfig().showRegionDeniedWarning;